INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (14, 1, 'theory', 'Квиз: компьютер и уровни абстракции');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (14, 1, 0, 'Что такое абстракция в разработке сложных систем?', '["Упрощённый рисунок системы","Исключение из рассмотрения тех подробностей, которые несущественны для текущей задачи","Замена сложных деталей на дешёвые","Описание системы одним предложением"]', 1, 'Абстракция позволяет работать на подходящем уровне и не помнить о нижних: политик смотрит на округа, а не на каждый двор.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (14, 1, 1, 'Чем архитектура отличается от микроархитектуры?', '["Ничем: это синонимы","Архитектура относится к памяти, микроархитектура — к процессору","Микроархитектура задаёт язык программирования","Архитектура — это то, что видит программист (команды, регистры); микроархитектура — то, как из вентилей это реализовано"]', 3, 'Core i7, 80486 и Athlon имеют одну архитектуру x86, но разную микроархитектуру: у них разные цена, скорость и расход энергии.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (14, 1, 2, 'Какой из принципов требует, чтобы у каждого модуля были чётко определённая функция и интерфейс?', '["Иерархичность","Регулярность","Модульность","Конструкторская дисциплина"]', 2, 'Модульность: модуль можно соединить с другими без побочных эффектов, ориентируясь только на интерфейс. Иерархичность делит систему на части, регулярность повторно использует одинаковые блоки.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (14, 1, 3, 'Сколько информации несёт переменная, принимающая одно из 8 равновероятных состояний?', '["1 бит","3 бита","8 бит","256 бит"]', 1, 'D = log₂ N: log₂ 8 = 3 бита. Двоичная переменная — 1 бит, а десять положений шестерни Бэббиджа — около 3,32 бита.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (14, 1, 4, 'Почему современные системы собирают из цифровых схем, хотя цифровые схемы — частный случай аналоговых?', '["Цифровые схемы дешевле всего","Аналоговых схем не существует","Цифровые схемы всегда быстрее","Ограничение двумя уровнями — конструкторская дисциплина: оно резко упрощает проектирование больших систем"]', 3, 'Дисциплина добровольно сужает выбор, но взамен можно собирать огромные системы, не думая о непрерывных величинах.');
INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (14, 2, 'theory', 'Квиз: транзистор и цифровая абстракция');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (14, 2, 0, 'Что превращает чистый кремний в полупроводник n-типа?', '["Нагрев до высокой температуры","Примесь бора: она создаёт дырку","Примесь из пятой группы, например мышьяк: она добавляет свободный электрон","Облучение светом"]', 2, 'Мышьяк имеет пять валентных электронов — один лишний, он свободно перемещается по решётке. Бор даёт дырку и делает кремний p-типа.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (14, 2, 1, 'Когда включён n-МОП транзистор?', '["Когда на затворе единица (достаточно высокое напряжение)","Когда на затворе ноль","Когда напряжение на стоке выше, чем на истоке","Всегда, пока подано питание"]', 0, 'Положительное напряжение на затворе создаёт под оксидом канал n-типа между истоком и стоком. p-МОП, наоборот, открывается нулём на затворе.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (14, 2, 2, 'Какие транзисторы стоят последовательно в схеме И-НЕ на КМОП?', '["Оба p-МОП","Один p-МОП и один n-МОП","Транзисторы вообще не соединяются","Оба n-МОП"]', 3, 'Выход должен уйти к земле, только если открыты оба n-МОП, поэтому они последовательно. p-МОП параллельны: хватит одного, чтобы подтянуть выход к единице.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (14, 2, 3, 'Пусть VOL = 0,33 В, VIL = 1,35 В. Чему равен запас шума по нулю NML?', '["0,33 В","1,02 В","1,35 В","1,68 В"]', 1, 'NML = VIL − VOL = 1,35 − 0,33 = 1,02 В. Это столько шума может добавиться к нулю на пути от источника к приёмнику, а вентиль всё ещё поймёт ноль.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (14, 2, 4, 'Как изменится динамическая мощность, если питание уменьшить вдвое при той же частоте и ёмкости?', '["Станет в четыре раза меньше","Станет вдвое меньше","Не изменится","Станет в восемь раз меньше"]', 0, 'P = ½ · C · V² · f зависит от квадрата напряжения: V вдвое меньше — P в четыре раза меньше. Поэтому напряжение питания снижают при каждой новой технологии.');
INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (14, 3, 'theory', 'Квиз: стандарты и открытые архитектуры');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (14, 3, 0, 'Что нужно, чтобы выход одного вентиля надёжно управлял входом другого?', '["Одинаковые названия семейств","Одинаковая длина проводов","Чтобы оба вентиля были из одного кристалла","VOH источника выше VIH приёмника и VOL ниже VIL"]', 3, 'Только если выходные уровни источника попадают в «разрешённые» входные диапазоны приёмника, шум не нарушит работу. Поэтому семейства логики описывают именно уровни.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (14, 3, 1, 'Что произойдёт, если подать сигнал 5 В на вход микросхемы, рассчитанной на 3,3 В без совместимости с 5 В?', '["Ничего: больше напряжение — надёжнее","Вход может быть повреждён","Сигнал станет нулём","Микросхема автоматически снизит напряжение"]', 1, 'Входные транзисторы рассчитаны на меньшее напряжение. В описании микросхем обязательно указывают, допустимы ли пятивольтовые сигналы.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (14, 3, 2, 'Что такое ISA?', '["Набор команд, регистров и правил работы с памятью — контракт между программой и процессором","Тип микросхемы памяти","Название операционной системы","Шина обмена данными"]', 0, 'Архитектура набора команд (Instruction Set Architecture) фиксирует то, что видит программист. Реализация — микроархитектура — может быть разной.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (14, 3, 3, 'Чем RISC-V отличается от x86 и ARM?', '["Он работает только на пяти ядрах","Он не поддерживает умножение","Его спецификация открыта: делать и менять процессоры можно без лицензионных платежей владельцу","Он существует только как эмулятор"]', 2, 'RISC-V ведёт открытая организация RISC-V International: спецификация свободна для всех, а расширения можно добавлять без нарушения совместимости.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (14, 3, 4, 'Что означает название RV32IMAC?', '["Процессор с 32 ядрами","32-битный RISC-V с базовым набором I и расширениями M (умножение), A (атомарные) и C (сжатые команды)","Четыре отдельных процессора","Версию 32 стандарта"]', 1, 'Модульность: к базе добавляют стандартные расширения, и производитель выбирает нужные. Расширения M, A, F, D, C перечисляют в названии.');
INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (14, 4, 'theory', 'Квиз: числа в компьютере');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (14, 4, 0, 'Сколько бит соответствует одной шестнадцатеричной цифре?', '["Два","Четыре","Восемь","Шестнадцать"]', 1, 'Цифра 0–F — это 16 значений, то есть ровно 4 бита; байт записывается двумя цифрами.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (14, 4, 1, 'Как записать −5 в восьми битах дополнительным кодом?', '["10000101","11111010","11111011","00000101"]', 2, 'Инвертируем 00000101 → 11111010 и прибавляем 1 → 11111011 (251 как беззнаковое).');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (14, 4, 2, 'Какой диапазон у знакового 8-битного числа в дополнительном коде?', '["от −127 до 127","от −128 до 127","от −255 до 255","от 0 до 255"]', 1, 'Нуль один, поэтому отрицательных значений на одно больше: от −128 до 127.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (14, 4, 3, 'Почему сравнение 0,1 + 0,2 == 0,3 в числах с плавающей точкой даёт «ложь»?', '["Это ошибка языка","0,1 и 0,2 в двоичной системе — бесконечные дроби, хранятся с погрешностью","Сложение чисел с плавающей точкой запрещено","Результат — целое число"]', 1, 'Десятичные дроби вроде 0.1 не представимы точно в двоичной системе; сравнивать надо с допуском.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (14, 4, 4, 'В каком порядке записано 0x12345678 в памяти little-endian процессора?', '["12 34 56 78","78 56 34 12","21 43 65 87","87 65 43 21"]', 1, 'Little-endian: первым лежит младший байт — 78 56 34 12; в сетевом порядке (big-endian) — 12 34 56 78.');
INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (14, 5, 'theory', 'Квиз: текст и защита данных');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (14, 5, 0, 'Чем кодовая точка Unicode отличается от кодировки UTF-8?', '["Ничем — это одно и то же","Кодовая точка — номер символа, UTF-8 — способ записать этот номер в байтах","UTF-8 — номер символа, кодовая точка — способ записи","Кодовая точка существует только для английских букв"]', 1, 'Unicode назначает номера символам, а UTF-8, UTF-16 и другие — способы превратить эти номера в байты.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (14, 5, 1, 'Сколько байт в UTF-8 занимает русская буква «Ж»?', '["Один","Два","Три","Четыре"]', 1, 'Кодовые точки U+0080…U+07FF записываются двумя байтами по шаблону 110xxxxx 10xxxxxx; для «Ж» это D0 96.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (14, 5, 2, 'Почему простая сумма байтов — плохая контрольная сумма?', '["Она слишком долго считается","Не замечает перестановку байтов и взаимно компенсирующие ошибки","Работает только для текста","Всегда равна нулю"]', 1, 'Сложение коммутативно: если поменять два байта местами, сумма не изменится. CRC зависит от позиции каждого бита.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (14, 5, 3, 'Что показывает синдром в коде Хэмминга (7,4)?', '["Число единиц в слове","Номер перевёрнутого бита (0 — ошибок нет)","Контрольную сумму файла","Длину слова"]', 1, 'Три проверки чётности образуют трёхбитное число — позицию ошибочного бита; его достаточно инвертировать.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (14, 5, 4, 'Для чего подходит CRC32, а для чего — SHA-256?', '["Оба одинаково защищают от злоумышленника","CRC32 — от случайных сбоев; SHA-256 — когда нужна защита от намеренной подмены","CRC32 — от подмены; SHA-256 — от сбоев","Ни для чего, они устарели"]', 1, 'CRC легко подогнать под нужное значение, поэтому для безопасности применяют криптографические хэши.');
INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (14, 6, 'theory', 'Квиз: логические элементы');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (14, 6, 0, 'Сколько строк в таблице истинности схемы с четырьмя входами?', '["4","8","16","32"]', 2, 'Каждый вход удваивает число комбинаций: 2 · 2 · 2 · 2 = 16. Поэтому большие схемы описывают формулами, а не таблицами.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (14, 6, 1, 'На входы вентиля И-НЕ подали A = 1 и B = 1. Что на выходе?', '["0","1","Зависит от питания","Неопределённое значение"]', 0, 'И даёт 1, а НЕ его инвертирует — получается 0. И-НЕ выдаёт единицу при любом наборе, кроме «обе единицы».');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (14, 6, 2, 'Как из одного вентиля И-НЕ получить инвертор?', '["Оставить один вход неподключённым","Подать на один вход постоянную единицу и убрать второй","Поставить два вентиля параллельно","Соединить оба входа вместе"]', 3, 'Когда оба входа равны A, выход равен не (A · A) = не A. Подключать вход «в воздухе» нельзя: его значение не определено.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (14, 6, 3, 'У схемы Y = A · E сигнал E равен нулю. Что на выходе?', '["Копия A","Инверсия A","Всегда 1","Всегда 0"]', 3, 'Ноль на одном входе И запирает вентиль: выход замирает в нуле, что бы ни приходило на A. Так работает «разрешение» (кран).');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (14, 6, 4, 'Как построить схему по таблице истинности «сумма произведений»?', '["Для каждой строки с единицей записать произведение входов (нулевые — с отрицанием) и сложить их","Для строк, где выход равен нулю, выписать суммы входов и перемножить их","Подключить все входы к одному вентилю ИЛИ","Перебрать вентили, пока таблица не совпадёт"]', 0, 'Каждое произведение «ловит» ровно одну строку таблицы. Сумма таких произведений даёт единицу в нужных строках и ноль во всех остальных — способ работает для любой таблицы.');
INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (14, 7, 'theory', 'Квиз: мультиплексоры и шины');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (14, 7, 0, 'Мультиплексор 2→1 имеет селектор S = 1. Что идёт на выход?', '["Вход A","Вход B","Отрицание A","Всегда ноль"]', 1, 'Формула Y = не S · A + S · B. При S = 1 первое слагаемое равно нулю, а второе — B.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (14, 7, 1, 'Сколько мультиплексоров 2→1 нужно, чтобы построить мультиплексор 4→1?', '["2","3","4","8"]', 1, 'Два на первом уровне (по паре входов), один на втором. Для 8→1 понадобится семь: 4 + 2 + 1.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (14, 7, 2, 'Какой код на входах дешифратора 2→4 зажигает линию Y2?', '["00","01","10","11"]', 2, 'Код читается как число: 10 — это два. Горит ровно одна линия с номером, равным коду.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (14, 7, 3, 'Что делает приоритетный шифратор, если одновременно горят I3 и I1?', '["Выдаёт код 00","Выдаёт код младшей линии (01)","Выдаёт код старшей линии (11)","Выдаёт ошибку и останавливается"]', 2, 'Приоритет у старшего номера: побеждает I3, выход 11. Дополнительный выход V показывает, что вход был активен.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (14, 7, 4, 'Как реализовать на мультиплексоре 4→1 функцию XOR от двух переменных?', '["Подать A и B на информационные входы","Подать A и B на селектор, а на информационные входы константы 0, 1, 1, 0","Подать константы на селектор","Так нельзя: XOR — не логическая функция"]', 1, 'Мультиплексор перебирает вход по номеру, заданному селектором. Если на входах записана таблица истинности, а на селекторе стоят переменные, получается любая функция этих переменных.');
INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (14, 8, 'theory', 'Квиз: защёлки и первая память');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (14, 8, 0, 'Что отличает последовательностную схему от комбинационной?', '["Выход зависит не только от текущих входов, но и от состояния (прошлого)","Число вентилей","Она работает только от такта","У неё всегда один выход"]', 0, 'Состояние — то, что схема помнит. Обычно оно хранится благодаря обратной связи: выход возвращается на вход.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (14, 8, 1, 'SR-защёлка на ИЛИ-НЕ: что произойдёт при S = 1, R = 0?', '["Q = 0","Q не определено","Q = 1","Защёлка хранит прежнее значение"]', 2, 'Единица на S устанавливает Q. При S = R = 0 защёлка хранит значение, а при S = R = 1 состояние запрещено.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (14, 8, 2, 'Какое состояние входов SR-защёлки на И-НЕ означает «хранить»?', '["Оба входа 0","Оба входа 1","Один 0, другой 1","Любое"]', 1, 'На И-НЕ активный уровень — ноль, поэтому две единицы ничего не меняют. Ноль на одном из входов устанавливает или сбрасывает.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (14, 8, 3, 'Что делает D-защёлка при E = 0?', '["Повторяет D","Сбрасывает Q","Устанавливает Q","Хранит последнее значение независимо от D"]', 3, 'Разрешение закрыто — вентили И перед SR выдают нули, и защёлка просто помнит.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (14, 8, 4, 'Почему защёлки заменяют триггерами, срабатывающими по фронту?', '["Триггеры дешевле","Защёлки не умеют хранить данные","Защёлка прозрачна, пока E открыто, и помехи проходят на выход; триггер берёт значение один раз по фронту","Триггеры не требуют питания"]', 2, 'Запись должна происходить в строго определённый момент. Тактовый сигнал и триггеры по фронту задают этот момент для всей схемы сразу.');
INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (14, 9, 'theory', 'Квиз: сумматоры и сравнение');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (14, 9, 0, 'Какие вентили образуют полусумматор?', '["Два И","XOR (для суммы) и И (для переноса)","ИЛИ и НЕ","Два ИЛИ-НЕ"]', 1, 'Сумма двух битов — исключающее ИЛИ, перенос — И. Полусумматор не принимает перенос снизу, поэтому для многоразрядных чисел нужен полный.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (14, 9, 1, 'Чему равен перенос полного сумматора при A = 1, B = 1, Cin = 0?', '["0","Не определено","Зависит от тактовой частоты","1"]', 3, 'Перенос равен единице, если единиц на входах хотя бы две. Здесь их две: сумма 0, перенос 1.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (14, 9, 2, 'Как сумматор-вычитатель вычисляет A − B?', '["Использует отдельную схему вычитания","Складывает A и B и инвертирует результат","Инвертирует B и подаёт единицу на вход переноса: A + не B + 1","Вычитает по одному биту без переноса"]', 2, 'В дополнительном коде −B = не B + 1. Сигнал Sub одновременно переключает XOR-вентили на входе B и вход переноса младшего разряда.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (14, 9, 3, 'В четырёх разрядах вычисляется 0111 + 0001 = 1000 в знаковом коде. Что произошло?', '["Знаковое переполнение: 7 + 1 дало −8","Ничего особенного","Перенос из старшего разряда","Ошибка сумматора"]', 0, 'Переноса нет, но результат вышел за диапазон: сложили два положительных, а получили отрицательное число. Это признак V.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (14, 9, 4, 'Почему сумматор с последовательным переносом медленный на большом числе разрядов?', '["В нём слишком мало вентилей","Он работает только на половине частоты","Результат нельзя считать до конца такта","Перенос должен пройти через все разряды по очереди"]', 3, 'Задержка растёт линейно с числом разрядов. Схемы ускоренного переноса вычисляют все переносы параллельно за счёт дополнительных вентилей.');
INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (14, 10, 'theory', 'Квиз: регистры и такт');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (14, 10, 0, 'Что такое фронт тактового сигнала?', '["Любой уровень единицы","Время одного периода","Переход из 0 в 1 (или из 1 в 0, в зависимости от триггера)","Ошибка передачи"]', 2, 'Триггеры срабатывают на фронте: в этот момент они берут значение со входа и хранят его до следующего фронта.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (14, 10, 1, 'Тактовая частота 2 ГГц. Чему равен период?', '["2 нс","0,5 нс","0,2 нс","5 нс"]', 1, 'T = 1 / f = 1 / (2·10⁹ Гц) = 0,5·10⁻⁹ с = 0,5 нс.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (14, 10, 2, 'Почему D-триггер строят из двух защёлок?', '["Одна защёлка слишком медленная","Чтобы удвоить объём памяти","Это требование стандарта","Чтобы значение передавалось на выход только в момент фронта, а не всё время, пока такт высокий"]', 3, 'Ведущая принимает вход при нулевом такте, ведомая выдаёт значение при единичном. Пока такт единица, ведущая закрыта и вход не влияет.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (14, 10, 3, 'Что получится, если инверсный выход Q̄ D-триггера подать на его же вход D?', '["Триггер зависнет","Выход переключается на каждом фронте — делитель частоты на два","Триггер станет запоминать единицу","Короткое замыкание"]', 1, 'D = не Q: на каждом фронте Q меняется на противоположное. Частота Q — половина частоты такта.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (14, 10, 4, 'Что ограничивает максимальную тактовую частоту синхронной схемы?', '["Самый длинный путь между двумя регистрами: период должен быть не меньше суммы задержек","Число триггеров","Напряжение питания","Длина провода такта"]', 0, 'T ≥ tcq + tлогики + tsetup. Чтобы поднять частоту, длинные пути укорачивают или разбивают регистрами — так возникает конвейер.');
INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (14, 11, 'theory', 'Квиз: АЛУ');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (14, 11, 0, 'Как устроено переключение операций в АЛУ?', '["Включается только нужный блок","Операции выполняются по очереди","Код операции подаётся на сумматор","Все операции вычисляются параллельно, а мультиплексор выбирает результат по коду операции"]', 3, 'Вентили работают одновременно, поэтому «лишние» вычисления ничего не стоят во времени. Выбор делает мультиплексор.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (14, 11, 1, 'Как АЛУ вычисляет A − B?', '["Отдельным блоком вычитания","Как A + не B + 1: инвертирует B и подаёт перенос единицу","Сдвигом B вправо","Сравнивая биты"]', 1, 'Вычитание сводится к сложению в дополнительном коде. Поэтому отдельная схема вычитания не нужна.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (14, 11, 2, 'Что означает флаг Z?', '["Результат равен нулю","Результат отрицателен","Было переполнение","Было вычитание"]', 0, 'Z (zero) равен единице, когда все биты результата — нули. Он используется в условиях «равно» и «не равно».');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (14, 11, 3, 'Зачем флаг V, если уже есть перенос C?', '["Они всегда равны","V нужен только для вычитания","C показывает выход за диапазон беззнаковых чисел, а V — знаковых","V — это то же, что Z"]', 2, '7 + 1 в четырёх знаковых разрядах даёт 1000 (−8): переноса нет, но результат неверен — это переполнение. 15 + 1 даёт перенос, но для беззнаковых это и есть выход за диапазон.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (14, 11, 4, 'Как процессор сравнивает два числа?', '["Побитово проверяет равенство каждой пары","Вычитает и смотрит на флаги; сам результат не сохраняется","Складывает числа и сравнивает с нулём","Использует мультиплексор"]', 1, 'Равенство — Z = 1, «меньше» определяется по переносу (беззнаковые) или по N xor V (знаковые). Из флагов строится сигнал T — условие перехода.');
INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (14, 12, 'theory', 'Квиз: память');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (14, 12, 0, 'Чем ПЗУ отличается от ОЗУ?', '["Содержимое ПЗУ задано схемой и не меняется, ОЗУ позволяет и читать, и записывать","ПЗУ быстрее","ОЗУ хранит данные без питания","ПЗУ нельзя читать"]', 0, 'ПЗУ «зашито» при изготовлении, ОЗУ — перезаписываемая память, которая забывает данные при выключении питания.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (14, 12, 1, 'Сколько слов можно адресовать тремя адресными битами?', '["3","6","8","9"]', 2, 'Количество различных комбинаций — 2³ = 8. Адрес из k бит различает 2 в степени k слов.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (14, 12, 2, 'Как в карте памяти из примера выбирается ПЗУ?', '["Адресом 7","Адресами 0–3: дешифратор зажигает сигнал Rom","Сигналом записи","Любым адресом"]', 1, 'Старшие биты адреса определяют, какое устройство выбрано. Горит ровно один из сигналов Rom, Ram, Io.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (14, 12, 3, 'Что происходит, если одновременно пришли Rd и Wr?', '["Выполняются обе операции","Ничего не происходит, схема зависает","Читается и пишется одно и то же","Запись побеждает, а выдача данных блокируется"]', 3, 'Читать и писать одновременно нельзя: We = CS · Wr, а Oe = CS · Rd · не We — выдача отключается.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (14, 12, 4, 'Почему ДОЗУ дешевле СОЗУ, но требует обновления?', '["В ней нет транзисторов","Она хранит данные только в регистрах","Ячейка — один транзистор и конденсатор, а заряд конденсатора утекает","ДОЗУ медленная, поэтому дешёвая"]', 2, 'СОЗУ строят на шести транзисторах — быстро, но дорого. В ДОЗУ данные хранит заряд, который со временем стекает, и его периодически обновляют.');
INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (14, 13, 'theory', 'Квиз: декодер команд и управление');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (14, 13, 0, 'Чем занимается декодер команд?', '["Вычисляет результат команды","Превращает код операции в управляющие сигналы для тракта данных","Хранит программу","Задаёт тактовую частоту"]', 1, 'Декодер связывает команду и тракт данных: по коду операции он выдаёт сигналы записи, выбора операции, перехода и остановки.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (14, 13, 1, 'При каком условии срабатывает переход JNZ?', '["Команда JNZ и аккумулятор равен нулю","Всегда при любой команде","Только в фазе исполнения","Команда JNZ и аккумулятор не равен нулю (Z = 0)"]', 3, 'Take = JNZ · не Z. Если аккумулятор равен нулю, JNZ не делает ничего.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (14, 13, 2, 'Как мультиплексор выбирает следующий адрес?', '["По тактовой частоте","По значению аккумулятора","Селектор Take выбирает между «PC + 1» и адресом прыжка k","Случайно"]', 2, 'При Take = 0 процессор идёт к следующей команде, при Take = 1 — прыгает на адрес из операнда.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (14, 13, 3, 'Для чего нужны фазы такта?', '["Чтобы управляющие сигналы срабатывали в нужный момент: выборка, декодирование, исполнение, запись","Чтобы увеличить частоту","Чтобы экономить память","Чтобы можно было остановить процессор"]', 0, 'Команда выполняется за несколько тактов. Секвенсор зажигает фазы по очереди, и каждый сигнал управления получается как И между фазой и условием.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (14, 13, 4, 'Почему остановка процессора реализуется защёлкой?', '["Так проще нарисовать схему","Защёлка быстрее вентиля","Это требование АЛУ","Нужно запомнить, что был Hlt, даже когда сам сигнал уже пропал"]', 3, 'Hlt присутствует только пока команда на шине. Защёлка Run сбрасывается им и остаётся нулём до нового сброса.');
INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (14, 14, 'theory', 'Квиз: процессор из блоков');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (14, 14, 0, 'Почему порты блоков имеют типы?', '["Чтобы экономить память","Чтобы блоки работали быстрее","Чтобы нельзя было соединить несовместимые шины — интерфейс проверяется до запуска","Это нужно только для красоты схемы"]', 2, 'Тип порта — договор: Word2 и Addr2 одинаковы по ширине, но означают разное. Несовместимое соединяют через переходник.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (14, 14, 1, 'Что делает блок выборки?', '["Хранит счётчик команд, выбирает следующий адрес и достаёт команду из ПЗУ","Выполняет арифметику","Расшифровывает код операции","Подаёт тактовый сигнал"]', 0, 'Выборка отвечает за PC, схему «следующий адрес» и ПЗУ. Зачем нужна команда — решает декодер.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (14, 14, 2, 'Какой сигнал возвращается из блока исполнения в декодер?', '["Тактовый","Адрес прыжка","Код операции","Флаг нуля Z (аккумулятор равен нулю)"]', 3, 'По Z декодер решает, брать ли переход JNZ. Другие сигналы идут от декодера к блокам.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (14, 14, 3, 'Сколько внешних входов у собранного процессора из этой главы?', '["Ни одного","Один: такт","Три: такт, сброс, останов","Четыре: по числу блоков"]', 1, 'Программа лежит в ПЗУ внутри блока выборки, всё остальное формируется внутри. Секвенсору нужен только такт.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (14, 14, 4, 'Что произойдёт в конце программы LDI 2, ADD 1, JNZ 1, HLT?', '["ADD вернёт аккумулятор к нулю (в двух разрядах), JNZ не прыгнет, а HLT остановит процессор","Процессор будет вечно прыгать","Сразу сработает HLT","Ошибка переполнения"]', 0, 'Аккумулятор проходит 2, 3, 0 (четыре не помещается в два бита). Когда он стал нулём, JNZ не прыгает, и доходим до HLT.');
INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (14, 15, 'theory', 'Квиз: ассемблер Мини-8');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (14, 15, 0, 'Чему всегда равен регистр r0 в Мини-8?', '["Последнему результату","Счётчику команд","Адресу диска","Нулю, что бы ни записывали"]', 3, 'Постоянный ноль удобен: он нужен для сравнений с нулём и копирования (mv) без отдельных команд.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (14, 15, 1, 'Как записать байт из r1 по адресу из r2?', '["lb r1, 0(r2)","sb r1, 0(r2)","li r1, r2","add r1, r2, r0"]', 1, 'sb — store byte: память [r2 + 0] = r1. lb наоборот читает байт из памяти в регистр.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (14, 15, 2, 'Во что ассемблер превращает inc r1?', '["В addi r1, r1, 1","В отдельную команду inc","В sub r1, r1, r0","В hlt"]', 0, 'inc — псевдокоманда: сокращение, которое ассемблер заменяет настоящей командой addi.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (14, 15, 3, 'Как в цикле по строке обнаружить конец?', '["По числу проходов","По регистру r0","По нулевому байту: bnez/beqz по прочитанному значению","По команде hlt"]', 2, 'Строки в памяти заканчиваются байтом 0. Прочитав его, цикл выходит.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (14, 15, 4, 'Как определить перенос при сложении младших байтов двух чисел?', '["По флагу C, он есть в Мини-8","Сравнением: если сумма меньше одного из слагаемых, был перенос","Через r0","Перенос не возникает"]', 1, 'В Мини-8 нет флага переноса. Результат меньше слагаемого при сложении по модулю 256 означает переполнение — используют bltu.');
INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (14, 16, 'theory', 'Квиз: RISC-V');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (14, 16, 0, 'Чему равен регистр x0 (zero)?', '["Всегда нулю","Счётчику команд","Адресу возврата","Последнему результату"]', 0, 'Запись в x0 ничего не меняет. Нулевой регистр нужен для сравнений с нулём, копирования и ряда псевдокоманд.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (14, 16, 1, 'Сколько бит занимает любая базовая команда RV32I?', '["8","16","32","64"]', 2, 'Все базовые команды — по 32 бита; форматы R, I, S, B, U, J отличаются лишь разбиением на поля.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (14, 16, 2, 'Как вычислить адрес элемента массива слов с номером i?', '["база + i","база + 4·i (сдвиг на два бита)","база · i","i − база"]', 1, 'Слово — четыре байта. slli t0, i, 2 умножает номер на четыре, затем прибавляется база.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (14, 16, 3, 'Какие регистры функция обязана вернуть прежними?', '["a0–a7","t0–t6","s0–s11","Никакие"]', 2, 's-регистры «сохраняемые»: если функция их использует, она сохраняет значения на стеке и восстанавливает. a и t — временные.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (14, 16, 4, 'Как программа выводит символ в консоль тренажёра?', '["Командой print","Чтением переключателей","Записью байта по адресу UART","Командой ecall без аргументов"]', 2, 'Периферия подключена к тем же шинам, что и память: запись байта по адресу UART (sb) выводит его в консоль.');
INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (14, 17, 'theory', 'Квиз: RISC-V на деле');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (14, 17, 0, 'Какой регистр содержит номер системного вызова в Linux на RISC-V?', '["a0","a7","ra","sp"]', 1, 'Номер вызова кладут в a7, аргументы — в a0, a1, a2…; затем выполняют ecall. write — 64, exit — 93.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (14, 17, 1, 'Что делает write(1, buf, 15)?', '["Читает 15 байт с клавиатуры","Завершает программу с кодом 15","Выделяет 15 байт памяти","Выводит 15 байтов из buf в стандартный вывод"]', 3, 'Первый аргумент — номер файла (1 = stdout), второй — адрес буфера, третий — число байтов.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (14, 17, 2, 'Почему print_uint заполняет буфер справа налево?', '["Так быстрее работает ecall","Так требует Linux","Цифры получаются от младшей к старшей: сначала остаток от деления на 10","Чтобы не использовать стек"]', 2, 'Остаток от деления на 10 — последняя цифра. Первой получается младшая, поэтому её кладут в конец буфера.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (14, 17, 3, 'Чему равен код возврата программы после exit(300), если оболочка покажет его командой echo $??', '["300","44","0","255"]', 1, 'Код возврата — один байт: 300 mod 256 = 44.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (14, 17, 4, 'Что показывает llvm-objdump -d?', '["Исходный текст программы","Содержимое переменных во время работы","Список установленных библиотек","Настоящие машинные слова и команды из собранного файла"]', 3, 'Дизассемблер превращает машинные слова в команды: удобно сверить с листингом тренажёра.');
INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (14, 18, 'theory', 'Квиз: иерархия памяти и кэш');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (14, 18, 0, 'Почему кэш в большинстве программ работает эффективно?', '["Он хранит всю память","Программы обращаются к памяти неслучайно: к недавним данным и к соседним адресам (локальность)","Кэш быстрее процессора","Кэш управляется пользователем"]', 1, 'Временная и пространственная локальность позволяют держать в маленьком быстром кэше те данные, которые понадобятся скоро.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (14, 18, 1, 'Какие поля выделяют из адреса в кэше?', '["Тег, индекс, смещение","Заголовок, тело, подпись","Страница, кадр, флаги","Банк, ряд, модуль"]', 0, 'Смещение — байт внутри строки, индекс — выбор места/набора, тег — подтверждение, что в строке нужный блок.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (14, 18, 2, 'Что такое конфликтный промах?', '["Кэш пуст","Блоки с одинаковым индексом вытесняют друг друга, хотя в кэше есть свободное место","Данных нет в памяти","Ошибка чтения"]', 1, 'В кэше с прямым отображением два блока с одним индексом борются за одну строку; ассоциативность смягчает проблему.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (14, 18, 3, 'Что экономит политика write-back по сравнению с write-through?', '["Место в кэше","Записи в память: при повторных записях в одну строку в память уходит одна запись при вытеснении","Время чтения","Электричество при выключении"]', 1, 'Строка помечается «грязной», и только при вытеснении её содержимое записывается в память.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (14, 18, 4, 'Кэш L1 отвечает за 1 такт при 5% промахов, а средний доступ к L2 — 50 тактов. Чему равно среднее время доступа?', '["1 такт","3,5 такта","50 тактов","51 такт"]', 1, 'AMAT = 1 + 0,05 × 50 = 3,5 такта.');
INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (14, 19, 'theory', 'Квиз: конвейер и производительность');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (14, 19, 0, 'Сколько тактов нужно идеальному 5-стадийному конвейеру на 100 команд?', '["500","104","100","5"]', 1, '5 + 100 − 1 = 104 такта: первая команда выходит через 5 тактов, дальше — по одной за такт.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (14, 19, 1, 'Что такое обход (forwarding)?', '["Пропуск команды при переходе","Передача результата АЛУ напрямую на вход следующей команды, не дожидаясь записи в регистр","Копирование кэша","Предсказание перехода"]', 1, 'Обход убирает паузы при зависимостях по данным между арифметическими командами.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (14, 19, 2, 'Почему даже с обходами остаётся пауза после команды загрузки (LW)?', '["Загрузка — самая длинная команда","Данные из памяти известны только после стадии MEM — позже, чем результат АЛУ","Регистры заняты","Кэш выключен"]', 1, 'Зависимость от загрузки стоит один такт; компилятор заполняет паузу независимой командой.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (14, 19, 3, 'Что показывает закон Амдала?', '["Ускорение части программы ограничено долей оставшегося времени","Закон Мура","Число транзисторов растёт вдвое","Частоту нельзя повышать"]', 0, 'Если ускорить 90% программы бесконечно сильно, всё равно получится не более 10×.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (14, 19, 4, 'Почему сравнивать процессоры по MIPS и частоте нельзя?', '["Эти величины всегда одинаковы","Разные процессоры тратят разное число команд и тактов на одну и ту же задачу","MIPS можно мерить только у ARM","Частота не влияет на скорость"]', 1, 'Честное сравнение — по времени выполнения реальных программ.');
INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (14, 20, 'theory', 'Квиз: виртуальная память');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (14, 20, 0, 'Что происходит при переводе виртуального адреса в физический?', '["Меняются все биты адреса","Номер страницы заменяется номером кадра, смещение внутри страницы остаётся прежним","Меняется только смещение","Адрес записывается на диск"]', 1, 'Страница и кадр одного размера, поэтому младшие биты (смещение) копируются как есть.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (14, 20, 1, 'Почему таблицы страниц делают многоуровневыми?', '["Так быстрее переводить","Чтобы не хранить огромную плоскую таблицу: таблицы пустых областей просто не создаются","Из соображений безопасности только","Это требует операционная система"]', 1, 'Плоская таблица для 48-битного адреса заняла бы 512 ГиБ на процесс; в четырёх уровнях по 512 записей выделяются лишь нужные ветви.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (14, 20, 2, 'Что хранит TLB?', '["Последние переводы «страница → кадр»","Содержимое оперативной памяти","Команды процессора","Список процессов"]', 0, 'Попадание в TLB даёт кадр за один такт, а обход таблиц нужен только при промахе.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (14, 20, 3, 'Что такое пробуксовка (thrashing)?', '["Перегрев процессора","Рабочее множество не помещается в память: страницы постоянно выгружаются и тут же загружаются","Ошибка в таблице страниц","Нехватка места на диске"]', 1, 'Система тратит почти всё время на обмен с диском; помогает добавление памяти или запуск меньшего числа программ.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (14, 20, 4, 'Зачем нужно копирование при записи (copy-on-write) после fork?', '["Чтобы замедлить дочерний процесс","Кадры остаются общими, пока кто-то не пишет — создание процесса дёшево и экономит память","Для шифрования страниц","Чтобы очистить кэш"]', 1, 'Копия кадра создаётся только в момент первой записи, всё остальное время родитель и ребёнок делят одни и те же страницы.');
INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (14, 21, 'theory', 'Квиз: ввод-вывод, шины и диски');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (14, 21, 0, 'Что такое ввод-вывод, отображённый на память (MMIO)?', '["Копирование файлов в память","Регистры устройства имеют адреса в адресном пространстве и доступны обычными командами чтения и записи","Устройство, подключённое к кэшу","Прерывание от памяти"]', 1, 'Запись по такому адресу — это команда устройству, а не изменение ОЗУ.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (14, 21, 1, 'Когда опрос выгоднее прерываний?', '["Когда события редки","Когда события идут очень часто — цена каждого прерывания перекрывает опрос","Никогда","Только для мыши"]', 1, 'Поэтому сетевые драйверы при высокой нагрузке переходят на опрос пачками (NAPI, DPDK).');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (14, 21, 2, 'Что даёт DMA?', '["Ускоряет процессор","Контроллер сам копирует данные между устройством и памятью, процессор занимается другим","Шифрует данные","Увеличивает кэш"]', 1, 'Процессору нужно лишь задать адрес, размер и направление; по завершении приходит одно прерывание.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (14, 21, 3, 'Из чего складывается время случайного обращения к HDD?', '["Только из передачи данных","Время поиска дорожки, ожидание нужного сектора (пол-оборота в среднем) и передача","Из задержки шины","Из времени отклика ядра"]', 1, 'При 7200 об/мин: ~8 мс поиск + ~4,2 мс вращение — около 12 мс на обращение.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (14, 21, 4, 'Как RAID с чётностью восстанавливает данные упавшего диска?', '["Берёт копию с зеркала","XOR всех оставшихся блоков (включая блок чётности) даёт потерянный блок","Читает из кэша","Перезаписывает нулями"]', 1, 'x XOR x = 0, поэтому XOR уцелевших блоков равен потерянному.');
INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (14, 22, 'theory', 'Квиз: параллелизм в архитектуре');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (14, 22, 0, 'Почему вместо повышения частоты процессоры получают всё больше ядер?', '["Ядра дешевле в производстве","Мощность растёт примерно как куб частоты: несколько медленных ядер дают ту же работу при меньшем нагреве","Так проще писать программы","Частота ограничена законом"]', 1, 'Два ядра на половинной частоте дают такую же суммарную производительность при четверти мощности.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (14, 22, 1, 'Что делает протокол когерентности кэшей (например, MESI)?', '["Ускоряет шину","Гарантирует, что все ядра в конечном счёте видят одно значение каждой ячейки: запись аннулирует чужие копии","Шифрует кэш","Распределяет потоки по ядрам"]', 1, 'Изменённая копия строки всегда единственная; остальные ядра получают её после чтения или запроса.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (14, 22, 2, 'Что такое ложное разделение (false sharing)?', '["Два потока пишут в одну переменную","Потоки пишут в разные переменные, лежащие в одной кэш-строке, и строка постоянно переезжает между ядрами","Ошибка в протоколе","Нехватка кэша"]', 1, 'Когерентность работает на уровне строк; помогает выравнивание «горячих» данных разных потоков по размеру строки.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (14, 22, 3, 'Как работает compare-and-swap (CAS)?', '["Обменивает значения двух регистров","Атомарно записывает новое значение, если текущее равно ожидаемому, и сообщает об успехе","Блокирует всю память","Копирует строку кэша"]', 1, 'Цикл «прочитать — попытаться заменить — повторить при неудаче» даёт атомарный счётчик без блокировки.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (14, 22, 4, 'Почему ветвления замедляют GPU?', '["У GPU нет команд перехода","Потоки варпа выполняют одну команду: при разных исходах условия выполняются обе ветви по очереди","Условия вычисляются на CPU","Ветвления запрещены"]', 1, 'Это называют расхождением (divergence); лучше всего GPU работает на однородных вычислениях.');
